modules.Signal:
--[[
	Signal
	Tipo:  ModuleScript
	Ruta:  ReplicatedStorage > StudioLite > Modules > Signal
	Sin dependencias.

	Evento mínimo. Se usa en lugar de BindableEvent cuando se pasan tablas
	(nodos del proyecto), porque BindableEvent copia las tablas y rompe su identidad.

	  local signal = Signal.new()
	  local connection = signal:Connect(function(...) end)
	  signal:Fire(...)
	  connection:Disconnect()
]]

local Signal = {}
Signal.__index = Signal

function Signal.new()
	return setmetatable({ _handlers = {} }, Signal)
end

function Signal:Connect(callback)
	local handler = { Callback = callback }
	table.insert(self._handlers, handler)
	return {
		Disconnect = function()
			local index = table.find(self._handlers, handler)
			if index then
				table.remove(self._handlers, index)
			end
		end,
	}
end

function Signal:Fire(...)
	for _, handler in ipairs(table.clone(self._handlers)) do
		task.spawn(handler.Callback, ...)
	end
end

function Signal:DisconnectAll()
	self._handlers = {}
end

return Signal
